import sys

def main():
    import sys
    input = sys.stdin.read().split()
    n = int(input[0])
    b = list(map(int, input[1:]))

    a = [0] * n
    a[0] = b[0] + 1
    for i in range(1, n):
        if b[i] == 0:
            a[i] = a[i - 1] + 1
        else:
            a[i] = (a[i - 1] // b[i]) * b[i] + b[i]
            if a[i] % b[i] != b[i]:
                print("NO")
                return

    for i in range(n):
        if a[i] <= b[i]:
            print("NO")
            return

    print("YES")
    print(" ".join(map(str, a)))

if __name__ == "__main__":
    main()
